BEGIN;
CREATE TABLE IF NOT EXISTS refresh_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),tenant_id uuid REFERENCES tenants(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz,replaced_by uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant_settings(tenant_id uuid PRIMARY KEY REFERENCES tenants(id),preferred_telephony_driver text NOT NULL DEFAULT 'auto',channel_limit integer NOT NULL DEFAULT 10 CHECK(channel_limit>0),cps_limit numeric(10,3) NOT NULL DEFAULT 1 CHECK(cps_limit>0),webrtc_domain text,turn_enabled boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_endpoints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL REFERENCES users(id),extension text NOT NULL,display_name text NOT NULL,secret_hash text NOT NULL,sip_ha1 text NOT NULL,status text NOT NULL DEFAULT 'offline' CHECK(status IN('offline','available','busy','break','wrap_up')),transport text NOT NULL DEFAULT 'wss',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,extension));
CREATE TABLE IF NOT EXISTS call_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),call_id uuid NOT NULL REFERENCES calls(id),event_type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS capacity_leases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),node_id uuid REFERENCES telephony_nodes(id),process_id uuid REFERENCES processes(id),call_id uuid NOT NULL,lease_owner text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(call_id));
CREATE TABLE IF NOT EXISTS provisioning_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),node_id uuid NOT NULL REFERENCES telephony_nodes(id),resource_type text NOT NULL,resource_id uuid NOT NULL,revision bigint NOT NULL,state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','processing','applied','failed')),attempts integer NOT NULL DEFAULT 0,last_error text,available_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(node_id,resource_type,resource_id,revision));
CREATE INDEX IF NOT EXISTS refresh_tokens_user_idx ON refresh_tokens(user_id,expires_at) WHERE revoked_at IS NULL;CREATE INDEX IF NOT EXISTS provisioning_ready_idx ON provisioning_jobs(state,available_at) WHERE state IN('queued','failed');CREATE INDEX IF NOT EXISTS call_events_call_idx ON call_events(call_id,occurred_at);
INSERT INTO schema_migrations(version) VALUES('002_runtime.sql') ON CONFLICT DO NOTHING;
COMMIT;
